<?php foreach($workflows as $workflow): $done=count(array_filter($workflow['tasks'],fn($t)=>$t['status']!=='pending'));$total=count($workflow['tasks']); ?><div class="card ems-card mb-3" id="workflow-<?= (int)$workflow['id'] ?>"><div class="card-header d-flex justify-content-between"><div><strong class="text-capitalize"><?= e($workflow['workflow_type']) ?></strong><div class="small text-secondary">Target <?= e(format_date($workflow['target_date'])) ?></div></div><span class="badge <?= $workflow['status']==='completed'?'text-bg-success':'text-bg-primary' ?>"><?= e(str_replace('_',' ',$workflow['status'])) ?></span></div><div class="card-body"><div class="d-flex justify-content-between small mb-2"><span><?= $done ?> of <?= $total ?> tasks</span><span><?= (int)round($done/max(1,$total)*100) ?>%</span></div><div class="progress-soft mb-3"><span style="width:<?= (int)round($done/max(1,$total)*100) ?>%"></span></div><div class="workflow-tasks"><?php foreach($workflow['tasks'] as $task): ?><div class="d-flex gap-3 align-items-start border-top py-3"><span class="setup-step-icon <?= $task['status']==='completed'?'is-done':'' ?>"><i data-lucide="<?= $task['status']==='completed'?'check':'circle' ?>"></i></span><div class="flex-grow-1"><strong><?= e($task['title']) ?></strong><div class="small text-secondary"><?= e($task['description']) ?></div><span class="badge text-bg-light border mt-1 text-capitalize"><?= e($task['category']) ?></span></div><?php if($workflow['status']!=='completed'): ?><form method="POST" action="/admin/employees/<?= (int)$employee['id'] ?>/workflow-tasks/<?= (int)$task['id'] ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $task['status']==='completed'?'pending':'completed' ?>"><button class="btn btn-sm <?= $task['status']==='completed'?'btn-soft':'btn-outline-success' ?>"><?= $task['status']==='completed'?'Reopen':'Complete' ?></button></form><?php endif; ?></div><?php endforeach; ?></div></div></div><?php endforeach; ?>
